    #[cfg_attr(test, test)]
    fn splitmix64_is_deterministic_in_seed() {
        let mut a = SplitMix64::new(777);
        let mut b = SplitMix64::new(777);
        for _ in 0..10 {
            assert_eq!(a.next_u64(), b.next_u64());
        }
    }

